insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (157, 12, 53, 62, 'سورة يوسف ٥٣ – ٦٢', '«وما أبرئ نفسي»، «اجعلني على خزائن الأرض»، وقدوم إخوة يوسف', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 157) = $j$[{"lbl": "الآيات ٥٣ – ٥٧", "q": "۞وَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّيٓۚ إِنَّ رَبِّي غَفُورٞ رَّحِيمٞ ﴿٥٣﴾ وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦٓ أَسۡتَخۡلِصۡهُ لِنَفۡسِيۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينٞ ﴿٥٤﴾ قَالَ ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمٞ ﴿٥٥﴾ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ يَتَبَوَّأُ مِنۡهَا حَيۡثُ يَشَآءُۚ نُصِيبُ بِرَحۡمَتِنَا مَن نَّشَآءُۖ وَلَا نُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ﴿٥٦﴾ وَلَأَجۡرُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ﴿٥٧﴾", "w": [["إلا ما رحم ربي", "إلا نفساً رحمها ربي بتوفيقها إلى تزكيتها وتطهيرها."], ["أستخلصه لنفسي", "أجعله من خُلصائي، من أهل مشورتي وأسراري."], ["مكين أمين", "ذو مكانة تتمكن بها من فعل ما تشاء، أمين مؤتمن على كل شيء."], ["خزائن الأرض", "خزائن الدولة في أرض مصر."], ["إني حفيظ عليم", "أحافظ على ما تُسنده إليّ وأحفظه، عليم بتدبيره."], ["يتبوأ", "ينزل ويحلّ حيث يشاء، بعد ما كان في غيابة الجب وضيق السجن."]], "m": "قال يوسف ﵇ بعد إعلان براءته: وما أبرئ نفسي، هضماً لنفسه، ولأنه قد همّ بضرب زليخا كما تقدّم، إن النفس البشرية لأمّارة بالسوء، إلا نفساً رحمها ربي بتوفيقها إلى تزكيتها بالإيمان وصالح الأعمال فتصبح نفساً مطمئنة تأمر بالخير، إن ربي غفور لمن تاب إليه رحيم بالمؤمنين. وقال الملك الريان بن الوليد: ائتوني به أستخلصه لنفسي، أجعله خالصاً لي أستشيره وأستعين به على مهام ملكي، فلما جاءه وكلّمه وسأله عن سني الخصب والجدب أجابه بما أثلج صدره من التدابير الحكيمة، فقال: إنك اليوم لدينا مكين أمين. قال: اجعلني على خزائن أرض مصر، أي حلّ محلّ العزيز الذي قد مات في تلك الأيام، إني حفيظ على ما أتولّى، عليم بكيفية الإدارة. وكذلك مكّنا ليوسف في الأرض ينزل منها حيث يشاء، نصيب برحمتنا من نشاء، ولا نضيع أجر المحسنين الذين نوفّيهم أجورهم في الدنيا والآخرة، ولأجر الآخرة خير للذين آمنوا وكانوا يتقون، ترغيباً في الإيمان والتقوى إذ بهما تُنال ولاية الله.", "h": ["فضيلة هضم النفس باتهامها بالنقص والتقصير.", "تحقيق الحكمة القائلة: المرء مخبوء تحت لسانه.", "جواز ذكر المرشَّح للعمل كحذق الصنعة ونحوه، ولا يُعدّ تزكية للنفس.", "فضيلة الإحسان في المعتقد والقول والعمل.", "فضل الإيمان والتقوى."], "k": "«وما أبرئ نفسي»… قالها يوسف وهو الصدّيق؛ فهل أتّهم نفسي أم أبرّئها دائماً؟"}, {"lbl": "الآيات ٥٨ – ٦٢", "q": "وَجَآءَ إِخۡوَةُ يُوسُفَ فَدَخَلُواْ عَلَيۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ ﴿٥٨﴾ وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِي بِأَخٖ لَّكُم مِّنۡ أَبِيكُمۡۚ أَلَا تَرَوۡنَ أَنِّيٓ أُوفِي ٱلۡكَيۡلَ وَأَنَا۠ خَيۡرُ ٱلۡمُنزِلِينَ ﴿٥٩﴾ فَإِن لَّمۡ تَأۡتُونِي بِهِۦ فَلَا كَيۡلَ لَكُمۡ عِندِي وَلَا تَقۡرَبُونِ ﴿٦٠﴾ قَالُواْ سَنُرَٰوِدُ عَنۡهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ ﴿٦١﴾ وَقَالَ لِفِتۡيَٰنِهِ ٱجۡعَلُواْ بِضَٰعَتَهُمۡ فِي رِحَالِهِمۡ لَعَلَّهُمۡ يَعۡرِفُونَهَآ إِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمۡ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٦٢﴾", "w": [["وجاء إخوة يوسف", "من أرض كنعان لما بلغهم أن ملك مصر يبيع الطعام."], ["وهم له منكرون", "غير عارفين أنه أخوهم."], ["ولما جهّزهم بجهازهم", "أكرمهم وزوّدهم بما يحتاجون إليه في سفرهم بعدما كال لهم ما ابتاعوه منه."], ["بأخ لكم من أبيكم", "هو بنيامين، لم يجئ معهم لأن والده لم يقدر على فراقه."], ["سنراود عنه أباه", "سنجتهد في طلبه منه."], ["وقال لفتيانه", "غلمانه وخدمه."], ["بضاعتهم", "دراهمهم التي جاؤوا يمتارون بها."]], "m": "بعد أن ولي يوسف أمر الوزارة، ومرّت سنوات الخصب وجاءت سنوات الجدب، احتاج أهل كنعان إلى الطعام، فبعث يعقوب ﵇ بنيه العشرة يمتارون. وجاء إخوة يوسف فدخلوا عليه فعرفهم وهم له منكرون لتغيّره بكِبَر السن وتغيّر أحواله. ولما كال لهم وحمّل لكل واحد بعيره بعد أن أكرمهم، وقد سألهم عن أحوالهم فأخبروه عن أبيهم وأخيهم، قال: ائتوني بأخ لكم من أبيكم، ألا ترون أني أوفي الكيل وأنا خير المضيفين؟ فإن لم تأتوني به فلا كيل لكم عندي ولا تقربون. قالوا: سنبذل جهدنا في طلبه من أبيه وإنا لفاعلون. وقال لغلمانه: اجعلوا دراهمهم في رحالهم من حيث لا يشعرون، لعلهم يعرفونها إذا رجعوا إلى أهلهم فيتحرّجون من أخذها فيرجعون بها ومعهم أخوهم، كل هذا رغبة من يوسف في إحضار أخيه الشقيق.", "h": ["عجيب تدبير الله تعالى، إذ رؤيا الملك وتعبير يوسف لها وظهورها كما عبّرها كان تدبيراً لولاية يوسف، ثم لمجيء إخوته يطلبون الطعام لأهليهم، ولتتم سلسلة الأحداث الآتية، فلا إله إلا الله ولا رب سواه.", "حسن تدبير يوسف ﵇ للإتيان بأخيه بنيامين تمهيداً للإتيان بالأسرة كلها.", "أثر الإيمان في السلوك، إذ عرف يوسف أن إخوته لا يستحلّون أكل مال بغير حقه، فجعل الدراهم في رحالهم ليرجعوا بها ومعهم أخوهم الذي يريد إحضاره."], "k": "«فعرفهم وهم له منكرون»… من ظلموه صاروا يطلبون طعامه؛ فهل أُحسن إلى من أساء إليّ إذا احتاجني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 157;
