قص والتقصير.", "تحقيق الحكمة القائلة: المرء مخبوء تحت لسانه.", "جواز ذكر المرشَّح للعمل كحذق الصنعة ونحوه، ولا يُعدّ تزكية للنفس.", "فضيلة الإحسان في المعتقد والقول والعمل.", "فضل الإيمان والتقوى."], "k": "«وما أبرئ نفسي»… قالها يوسف وهو الصدّيق؛ فهل أتّهم نفسي أم أبرّئها دائماً؟"}, {"lbl": "الآيات ٥٨ – ٦٢", "q": "وَجَآءَ إِخۡوَةُ يُوسُفَ فَدَخَلُواْ عَلَيۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ ﴿٥٨﴾ وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِي بِأَخٖ لَّكُم مِّنۡ أَبِيكُمۡۚ أَلَا تَرَوۡنَ أَنِّيٓ أُوفِي ٱلۡكَيۡلَ وَأَنَا۠ خَيۡرُ ٱلۡمُنزِلِينَ ﴿٥٩﴾ فَإِن لَّمۡ تَأۡتُونِي بِهِۦ فَلَا كَيۡلَ لَكُمۡ عِندِي وَلَا تَقۡرَبُونِ ﴿٦٠﴾ قَالُواْ سَنُرَٰوِدُ عَنۡهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ ﴿٦١﴾ وَقَالَ لِفِتۡيَٰنِهِ ٱجۡعَلُواْ بِضَٰعَتَهُمۡ فِي رِحَالِهِمۡ لَعَلَّهُمۡ يَعۡرِفُونَهَآ إِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمۡ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٦٢﴾", "w": [["وجاء إخوة يوسف", "من أرض كنعان لما بلغهم أن ملك مصر يبيع الطعام."], ["وهم له منكرون", "غير عارفين أنه أخوهم."], ["ولما جهّزهم بجهازهم", "أكرمهم وزوّدهم بما يحتاجون إليه في سفرهم بعدما كال لهم ما ابتاعوه منه."], ["بأخ لكم من أبيكم", "هو بنيامين، لم يجئ معهم لأن والده لم يقدر على فراقه."], ["سنراود عنه أباه", "سنجتهد في طلبه منه."], ["وقال لفتيانه", "غلمانه وخدمه."], ["بضاعتهم", "دراهمهم التي جاؤوا يمتارون بها."]], "m": "بعد أن ولي يوسف أمر الوزارة، ومرّت سنوات الخصب وجاءت سنوات الجدب، احتاج أهل كنعان إلى الطعام، فبعث يعقوب ﵇ بنيه العشرة يمتارون. وجاء إخوة يوسف فدخلوا عليه فعرفهم وهم له منكرون لتغيّره بكِبَر السن وتغيّر أحواله. ولما كال لهم وحمّل لكل واحد بعيره بعد أن أكرمهم، وقد سألهم عن أحوالهم فأخبروه عن أبيهم وأخيهم، قال: ائتوني بأخ لكم من أبيكم، ألا ترون أني أوفي الكيل وأنا خير المضيفين؟ فإن لم تأتوني به فلا كيل لكم عندي ولا تقربون. قالوا: سنبذل جهدنا في طلبه من أبيه وإنا لفاعلون. وقال لغلمانه: اجعلوا دراهمهم في رحالهم من حيث لا يشعرون، لعلهم يعرفونها إذا رجعوا إلى أهلهم فيتحرّجون من أخذها فيرجعون بها ومعهم أخوهم، كل هذا رغبة من يوسف في إحضار أخيه الشقيق.", "h": ["عجيب تدبير الله تعالى، إذ رؤيا الملك وتعبير يوسف لها وظهورها كما عبّرها كان تدبيراً لولاية يوسف، ثم لمجيء إخوته يطلبون الطعام لأهليهم، ولتتم سلسلة الأحداث الآتية، فلا إله إلا الله ولا رب سواه.", "حسن تدبير يوسف ﵇ للإتيان بأخيه بنيامين تمهيداً للإتيان بالأسرة كلها.", "أثر الإيمان في السلوك، إذ عرف يوسف أن إخوته لا يستحلّون أكل مال بغير حقه، فجعل الدراهم في رحالهم ليرجعوا بها ومعهم أخوهم الذي يريد إحضاره."], "k": "«فعرفهم وهم له منكرون»… من ظلموه صاروا يطلبون طعامه؛ فهل أُحسن إلى من أساء إليّ إذا احتاجني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (158, 12, 63, 76, 'سورة يوسف ٦٣ – ٧٦', '«فالله خير حافظاً»، وصواع الملك: «وفوق كل ذي علم عليم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 158) = $j$[{"lbl": "الآيات ٦٣ – ٦٧", "q": "فَلَمَّا رَجَعُوٓاْ إِلَىٰٓ أَبِيهِمۡ قَالُواْ يَـٰٓأَبَانَا مُنِعَ مِنَّا ٱلۡكَيۡلُ فَأَرۡسِلۡ مَعَنَآ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ﴿٦٣﴾ قَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَمَآ أَمِنتُكُمۡ عَلَىٰٓ أَخِيهِ مِن قَبۡلُ فَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّـٰحِمِينَ ﴿٦٤﴾ وَلَمَّا فَتَحُواْ مَتَٰعَهُمۡ وَجَدُواْ بِضَٰعَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡۖ قَالُواْ يَـٰٓأَبَانَا مَا نَبۡغِيۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتۡ إِلَيۡنَاۖ وَنَمِيرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَيۡلَ بَعِيرٖۖ ذَٰلِكَ كَيۡلٞ يَسِيرٞ ﴿٦٥﴾ قَالَ لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقٗا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمۡۖ فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ ﴿٦٦﴾ وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ﴿٦٧﴾", "w": [["نكتل", "نحصل على الكيل المطلوب."], ["موثقاً", "عهداً مؤكّداً باليمين."], ["إلا أن يحاط بكم", "تهلكوا عن آخركم."], ["من شيء", "أي أراد الله خلافه."]], "m": "رجع إخوة يوسف إلى أبيهم بأرض كنعان فقالوا: يا أبانا مُنع منا الكيل إلا أن نأتي بأخينا بنيامين، فأرسله معنا نكتل، وإنا له لحافظون. قال: هل آمنكم عليه إلا كما أمنتكم على أخيه من قبل؟ فالله خير حافظاً وهو أرحم الراحمين. ولما فتحوا متاعهم وجدوا دراهمهم رُدّت إليهم، قالوا: يا أبانا ما نبغي؟ هذه بضاعتنا رُدّت إلينا، فأرسل معنا أخانا ونمير أهلنا ونحفظ أخانا ونزداد كيل بعير، إذ كان الملك لا يبيع للنفر الواحد إلا حمل بعير لحاجة الناس في سنوات الجدب. قال: لن أرسله معكم حتى تعطوني عهداً مؤكداً باليمين لتأتُنّني به إلا أن يحاط بكم فتهلكوا جميعاً، فلما أعطوه عهدهم قال: الله على ما نقول وكيل. ولما أرادوا السفر حملته العاطفة الأبوية على أن قال: يا بنيّ لا تدخلوا وأنتم أحد عشر رجلاً من باب واحد فتُسرع إليكم العين، وادخلوا من أبواب متفرقة، وما أغني عنكم من الله من شيء، إن الحكم إلا لله، عليه توكلت، وعليه فليتوكل المتوكلون، لأنه الكافي ولا كافي على الحقيقة إلا هو.", "h": ["بيان مدى توكّل يعقوب ﵇ على الله وثقته في ربه عز وجل، ومعرفته بأسمائه وصفاته.", "جواز أخذ العهد المؤكّد في الأمور الهامة ولو على أقرب الناس كالأبناء.", "لا بأس بتخوّف المؤمن من إصابة العين وأخذ الحيطة للوقاية منها، مع اعتقاد أن ذلك لا يغني من الله شيئاً، وأن الحكم لله وحده في خلقه.", "وجوب التوكل على الله تعالى، وإمضاء العمل الذي تعيّن، وتفويض أمر ما يحدث لله."], "k": "«فالله خير حافظاً»… أحبابي الذين أخاف عليهم، هل أستودعهم الله كل يوم؟"}, {"lbl": "الآيات ٦٨ – ٧٢", "q": "وَلَمَّا دَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٦٨﴾ وَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَخَاهُۖ قَالَ إِنِّيٓ أَنَا۠ أَخُوكَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَعۡمَلُونَ ﴿٦٩﴾ فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ ﴿٧٠﴾ قَالُواْ وَأَقۡبَلُواْ عَلَيۡهِم مَّاذَا تَفۡقِدُونَ ﴿٧١﴾ قَالُواْ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمۡلُ بَعِيرٖ وَأَنَا۠ بِهِۦ زَعِيمٞ ﴿٧٢﴾", "w": [["إلا حاجة في نفس يعقوب", "هي إرادة دفع العين عن أولاده شفقةً عليهم."], ["آوى إليه أخاه", "ضمّه إليه أثناء الأكل وأثناء المبيت."], ["فلا تبتئس", "لا تحزن."], ["جعل السقاية", "صاع الملك، وهو من ذهب كان يشرب فيه، ثم جعله مكيالاً يكيل به."], ["أذّن مؤذن", "نادى منادٍ."], ["أيتها العير", "أي القافلة."], ["صواع الملك", "صاع الملك، فالصاع والصواع بمعنى واحد."], ["وأنا به زعيم", "بالحمل كفيل."]], "m": "وصلوا إلى مصر ودخلوا من أبواب متعددة كما أمرهم أبوهم، ما كان ذلك يغني عنهم من الله من شيء، إلا حاجة في نفس يعقوب، وهي خوف العين عليهم، قضاها، وإنه لذو علم وعمل لتعليمنا إياه، ولكن أكثر الناس لا يعلمون عن الله صفات جلاله وكماله ومحابّه ومساخطه. ولما دخلوا على يوسف ضمّ إليه أخاه بنيامين، إذ جعل كل اثنين في غرفة فبقي بنيامين فقال: هذا ينام معي، وأعلمه أنه أخوه يوسف، وألّا يحزن بما كان إخوته عملوه، وأنه سيحتال على بقائه معه فلا يخبر إخوته بشيء. فلما جهّزهم بجهازهم جعل خفيةً صاع الملك في رحل أخيه، ثم لما تحركت القافلة نادى منادٍ: أيتها القافلة إنكم لسارقون. قالوا وأقبلوا عليهم: ماذا تفقدون؟ قالوا: نفقد صواع الملك، ولمن جاء به حمل بعير مكافأة، وأنا بإعطائه كفيل.", "h": ["بيان فضل العلم وأهله.", "تقرير حقيقة، وهي أن أكثر الناس لا يعلمون.", "حسن تدبير يوسف للإبقاء على أخيه معه بعد ذهاب إخوته.", "مشروعية إعطاء المكافآت لمن يقوم بعمل معيّن، وهي الجعالة في الفقه.", "مشروعية الكفالة، والكفيل غارم."], "k": "«إني أنا أخوك فلا تبتئس»… كلمة طمأنينة في وقتها تُذهب حزناً طويلاً؛ فمن أطمئنه اليوم؟"}, {"lbl": "الآيات ٧٣ – ٧٦", "q": "قَالُواْ تَٱللَّهِ لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِي ٱلۡأَرۡضِ وَمَا كُنَّا سَٰرِقِينَ ﴿٧٣﴾ قَالُواْ فَمَا جَزَـٰٓؤُهُۥٓ إِن كُنتُمۡ كَٰذِبِينَ ﴿٧٤﴾ قَالُواْ جَزَـٰٓؤُهُۥ مَن وُجِدَ فِي رَحۡلِهِۦ فَهُوَ جَزَـٰٓؤُهُۥۚ كَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ ﴿٧٥﴾ فَبَدَأَ بِأَوۡعِيَتِهِمۡ قَبۡلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن وِعَآءِ أَخِيهِۚ كَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ فِي دِينِ ٱلۡمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ ﴿٧٦﴾", "w": [["تالله", "أي والله."], ["لنفسد في الأرض", "بارتكاب المعاصي وغشيان الذنوب."], ["وما كنا سارقين", "لم نسرق الصواع، كما أنّا لم نسرق من قبل."], ["من وُجد في رحله فهو جزاؤه", "يُؤخذ بالسرقة رقيقاً."], ["كذلك نجزي الظالمين", "أي في شريعتنا."], ["من وعاء أخيه", "من وعاء أخيه الموجود في رحله."], ["كذلك كدنا ليوسف", "يسّرنا له هذا الكيد الذي توصّل به إلى أمر محمود."], ["في دين الملك", "في شرعه، إذ كان يضرب السارق ويغرّمه."], ["نرفع درجات من نشاء", "كما رفعنا يوسف ﵇."]], "m": "لما أُعلن عن سرقة صواع الملك وأوقفت القافلة للتفتيش قال إخوة يوسف: تالله لقد علمتم ما جئنا لنفسد في الأرض بالسرقة وغشيان الذنوب، وإنما جئنا للميرة، وما كنا سارقين في يوم من الأيام. قال رجال الملك: فما جزاؤه إن كنتم كاذبين؟ قالوا: جزاؤه من وُجد في رحله فهو جزاؤه، يريدون أن السارق يُسترقّ بالسرقة، كذلك نجزي الظالمين في شريعتنا. فبدأ بأوعيتهم واحداً بعد واحد، وأخّر وعاء أخيه دفعاً للتهمة، ثم استخرجها من وعاء أخيه. كذلك يسّرنا ليوسف هذا الكيد، ما كان ليأخذ أخاه في شرع ملك مصر، إذ كان يضرب السارق ويغرّمه، إلا أن يشاء الله. نرفع درجات من نشاء في العلم كما رفعنا يوسف، وفوق كل ذي علم من الناس عليم، حتى ينتهي العلم إلى الله العليم الذي لا أعلم منه، ولولاه لما علم أحد شيئاً.", "h": ["جواز الحلف بالله تعالى للحاجة.", "مشروعية دفع التهمة عن النفس البريئة.", "معرفة حكم السرقة في شرعة يعقوب ﵇.", "بيان حسن تدبير الله تعالى لأوليائه.", "بيان حكم السرقة في القانون المصري على عهد يوسف ﵇.", "علوّ مقام يوسف ﵇ في العلم.", "تقرير قاعدة: «وفوق كل ذي علم عليم»، إلى أن ينتهي العلم إلى الله تعالى."], "k": "«وفوق كل ذي علم عليم»… مهما تعلّمت، فهل يبقى التواضع رفيق علمي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 158;
insert into public.tdb_cards(topic, i, body) select 158, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٣ – ٦٧", "q": "فَلَمَّا رَجَعُوٓاْ إِلَىٰٓ أَبِيهِمۡ قَالُواْ يَـٰٓأَبَانَا مُنِعَ مِنَّا ٱلۡكَيۡلُ فَأَرۡسِلۡ مَعَنَآ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ﴿٦٣﴾ قَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَمَآ أَمِنتُكُمۡ عَلَىٰٓ أَخِيهِ مِن قَبۡلُ فَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّـٰحِمِينَ ﴿٦٤﴾ وَلَمَّا فَتَحُواْ مَتَٰعَهُمۡ وَجَدُواْ بِضَٰعَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡۖ قَالُواْ يَـٰٓأَبَانَا مَا نَبۡغِيۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتۡ إِلَيۡنَاۖ وَنَمِيرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَيۡلَ بَعِيرٖۖ ذَٰلِكَ كَيۡلٞ يَسِيرٞ ﴿٦٥﴾ قَالَ لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقٗا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمۡۖ فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ ﴿٦٦﴾ وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ﴿٦٧﴾", "w": [["نكتل", "نحصل على الكيل المطلوب."], ["موثقاً", "عهداً مؤكّداً باليمين."], ["إلا أن يحاط بكم", "تهلكوا عن آخركم."], ["من شيء", "أي أراد الله خلافه."]], "m": "رجع إخوة يوسف إلى أبيهم بأرض كنعان فقالوا: يا أبانا مُنع منا الكيل إلا أن نأتي بأخينا بنيامين، فأرسله معنا نكتل، وإنا له لحافظون. قال: هل آمنكم عليه إلا كما أمنتكم على أخيه من قبل؟ فالله خير حافظاً وهو أرحم الراحمين. ولما فتحوا متاعهم وجدوا دراهمهم رُدّت إليهم، قالوا: يا أبانا ما نبغي؟ هذه بضاعتنا رُدّت إلينا، فأرسل معنا أخانا ونمير أهلنا ونحفظ أخانا ونزداد كيل بعير، إذ كان الملك لا يبيع للنفر الواحد إلا حمل بعير لحاجة الناس في سنوات الجدب. قال: لن أرسله معكم حتى تعطوني عهداً مؤكداً باليمين لتأتُنّني به إلا أن يحاط بكم فتهلكوا جميعاً، فلما أعطوه عهدهم قال: الله على ما نقول وكيل. ولما أرادوا السفر حملته العاطفة الأبوية على أن قال: يا بنيّ لا تدخلوا وأنتم أحد عشر رجلاً من باب واحد فتُسرع إليكم العين، وادخلوا من أبواب متفرقة، وما أغني عنكم من الله من شيء، إن الحكم إلا لله، عليه توكلت، وعليه فليتوكل المتوكلون، لأنه الكافي ولا كافي على الحقيقة إلا هو.", "h": ["بيان مدى توكّل يعقوب ﵇ على الله وثقته في ربه عز وجل، ومعرفته بأسمائه وصفاته.", "جواز أخذ العهد المؤكّد في الأمور الهامة ولو على أقرب الناس كالأبناء.", "لا بأس بتخوّف المؤمن من إصابة العين وأخذ الحيطة للوقاية منها، مع اعتقاد أن ذلك لا يغني من الله شيئاً، وأن الحكم لله وحده في خلقه.", "وجوب التوكل على الله تعالى، وإمضاء العمل الذي تعيّن، وتفويض أمر ما يحدث لله."], "k": "«فالله خير حافظاً»… أحبابي الذين أخاف عليهم، هل أستودعهم الله كل يوم؟"}, {"lbl": "الآيات ٦٨ – ٧٢", "q": "وَلَمَّا دَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٦٨﴾ وَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَخَاهُۖ قَالَ إِنِّيٓ أَنَا۠ أَخُوكَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَعۡمَلُونَ ﴿٦٩﴾ فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ ﴿٧٠﴾ قَالُواْ وَأَقۡبَلُواْ عَلَيۡهِم مَّاذَا تَفۡقِدُونَ ﴿٧١﴾ قَالُواْ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمۡلُ بَعِيرٖ وَأَنَا۠ بِهِۦ زَعِيمٞ ﴿٧٢﴾", "w": [["إلا حاجة في نفس يعقوب", "هي إرادة دفع العين عن أولاده شفقةً عليهم."], ["آوى إليه أخاه", "ضمّه إليه أثناء الأكل وأثناء المبيت."], ["فلا تبتئس", "لا تحزن."], ["جعل السقاية", "صاع الملك، وهو من ذهب كان يشرب فيه، ثم جعله مكيالاً يكيل به."], ["أذّن مؤذن", "نادى منادٍ."], ["أيتها العير", "أي القافلة."], ["صواع الملك", "صاع الملك، فالصاع والصواع بمعنى واحد."], ["وأنا به زعيم", "بالحمل كفيل."]], "m": "وصلوا إلى مصر ودخلوا من أبواب متعددة كما أمرهم أبوهم، ما كان ذلك يغني عنهم من الله من شيء، إلا حاجة في نفس يعقوب، وهي خوف العين عليهم، قضاها، وإنه لذو علم وعمل لتعليمنا إياه، ولكن أكثر الناس لا يعلمون عن الله صفات جلاله وكماله ومحابّه ومساخطه. ولما دخلوا على يوسف ضمّ إليه أخاه بنيامين، إذ جعل كل اثنين في غرفة فبقي بنيامين فقال: هذا ينام معي، وأعلمه أنه أخوه يوسف، وألّا يحزن بما كان إخوته عملوه، وأنه سيحتال على بقائه معه فلا يخبر إخوته بشيء. فلما جهّزهم بجهازهم جعل خفيةً صاع الملك في رحل أخيه، ثم لما تحركت القافلة نادى منادٍ: أيتها القافلة إنكم لسارقون. قالوا وأقبلوا عليهم: ماذا تفقدون؟ قالوا: نفقد صواع الملك، ولمن جاء به حمل بعير مكافأة، وأنا بإعطائه كفيل.", "h": ["بيان فضل العلم وأهله.", "تقرير حقيقة، وهي أن أكثر الناس لا يعلمون.", "حسن تدبير يوسف للإبقاء على أخيه معه بعد ذهاب إخوته.", "مشروعية إعطاء المكافآت لمن يقوم بعمل معيّن، وهي الجعالة في الفقه.", "مشروعية الكفالة، والكفيل غارم."], "k": "«إني أنا أخوك فلا تبتئس»… كلمة طمأنينة في وقتها تُذهب حزناً طويلاً؛ فمن أطمئنه اليوم؟"}, {"lbl": "الآيات ٧٣ – ٧٦", "q": "قَالُواْ تَٱللَّهِ لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِي ٱلۡأَرۡضِ وَمَا كُنَّا سَٰرِقِينَ ﴿٧٣﴾ قَالُواْ فَمَا جَزَـٰٓؤُهُۥٓ إِن كُنتُمۡ كَٰذِبِينَ ﴿٧٤﴾ قَالُواْ جَزَـٰٓؤُهُۥ مَن وُجِدَ فِي رَحۡلِهِۦ فَهُوَ جَزَـٰٓؤُهُۥۚ كَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ ﴿٧٥﴾ فَبَدَأَ بِأَوۡعِيَتِهِمۡ قَبۡلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن وِعَآءِ أَخِيهِۚ كَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ فِي دِينِ ٱلۡمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ ﴿٧٦﴾", "w": [["تالله", "أي والله."], ["لنفسد في الأرض", "بارتكاب المعاصي وغشيان الذنوب."], ["وما كنا سارقين", "لم نسرق الصواع، كما أنّا لم نسرق من قبل."], ["من وُجد في رحله فهو جزاؤه", "يُؤخذ بالسرقة رقيقاً."], ["كذلك نجزي الظالمين", "أي في شريعتنا."], ["من وعاء أخيه", "من وعاء أخيه الموجود في رحله."], ["كذلك كدنا ليوسف", "يسّرنا له هذا الكيد الذي توصّل به إلى أمر محمود."], ["في دين الملك", "في شرعه، إذ كان يضرب السارق ويغرّمه."], ["نرفع درجات من نشاء", "كما رفعنا يوسف ﵇."]], "m": "لما أُعلن عن سرقة صواع الملك وأوقفت القافلة للتفتيش قال إخوة يوسف: تالله لقد علمتم ما جئنا لنفسد في الأرض بالسرقة وغشيان الذنوب، وإنما جئنا للميرة، وما كنا سارقين في يوم من الأيام. قال رجال الملك: فما جزاؤه إن كنتم كاذبين؟ قالوا: جزاؤه من وُجد في رحله فهو جزاؤه، يريدون أن السارق يُسترقّ بالسرقة، كذلك نجزي الظالمين في شريعتنا. فبدأ بأوعيتهم واحداً بعد واحد، وأخّر وعاء أخيه دفعاً للتهمة، ثم استخرجها من وعاء أخيه. كذلك يسّرنا ليوسف هذا الكيد، ما كان ليأخذ أخاه في شرع ملك مصر، إذ كان يضرب السارق ويغرّمه، إلا أن يشاء الله. نرفع درجات من نشاء في العلم كما رفعنا يوسف، وفوق كل ذي علم من الناس عليم، حتى ينتهي العلم إلى الله العليم الذي لا أعلم منه، ولولاه لما علم أحد شيئاً.", "h": ["جواز الحلف بالله تعالى للحاجة.", "مشروعية دفع التهمة عن النفس البريئة.", "معرفة حكم السرقة في شرعة يعقوب ﵇.", "بيان حسن تدبير الله تعالى لأوليائه.", "بيان حكم السرقة في القانون المصري على عهد يوسف ﵇.", "علوّ مقام يوسف ﵇ في العلم.", "تقرير قاعدة: «وفوق كل ذي علم عليم»، إلى أن ينتهي العلم إلى الله تعالى."], "k": "«وفوق كل ذي علم عليم»… مهما تعلّمت، فهل يبقى التواضع رفيق علمي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (159, 12, 77, 93, 'سورة يوسف ٧٧ – ٩٣', '«إنما أشكو بثي وحزني إلى الله»، «ولا تيأسوا من روح الله»، و«أنا يوسف»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 159) = $j$[{"lbl": "الآيات ٧٧ – ٧٩", "q": "۞قَالُوٓاْ إِن يَسۡرِقۡ فَقَدۡ سَرَقَ أَخٞ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا يُوسُفُ فِي نَفۡسِهِۦ وَلَمۡ يُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرّٞ مَّكَانٗاۖ وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ ﴿٧٧﴾ قَالُواْ يَـٰٓأَيُّهَا ٱلۡعَزِيزُ إِنَّ لَهُۥٓ أَبٗا شَيۡخٗا كَبِيرٗا فَخُذۡ أَحَدَنَا مَكَانَهُۥٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ ﴿٧٨﴾ قَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذٗا لَّظَٰلِمُونَ ﴿٧٩﴾", "w": [["فأسرّها يوسف في نفسه", "لم يُظهرها لهم."], ["أنتم شر مكاناً", "شرّ منزلة ممن رميتموه بالسرقة."], ["بما تصفون", "بحقيقة ما تصفون، أي تذكرون."], ["أباً شيخاً كبيراً", "أي يعقوب ﵇."], ["معاذ الله", "نعوذ بالله من أن نأخذ من لم نجد متاعنا عنده."], ["متاعنا", "الصواع."]], "m": "بعد أن استخرج يوسف الصواع من متاع أخيه وتقرّر ظاهراً أن بنيامين سرق، قال إخوته: إن يسرق فقد سرق أخ له من قبل، يعنون يوسف أيام صباه، كان يأخذ الطعام فيعطيه للمساكين، وأخذ صنماً لأبي أمه فكسره حتى لا يعبده، وليس هذا من السرقة المذمومة بل هو محمود. فأسرّها يوسف في نفسه ولم يُظهرها لهم، وقال: أنتم شرّ منزلة ممن رميتموه بالسرقة، والله أعلم بحقيقة ما تذكرون. فلما سمعوا ما في قوله من الصرامة قالوا مستعطفين: يا أيها العزيز إن له أباً شيخاً كبيراً يعزّ عليه فراقه، فخذ أحدنا مكانه إنا نراك من المحسنين. قال: معاذ الله أن نأخذ إلا من وجدنا متاعنا عنده، إنا إذاً لظالمون إن أخذنا من لم يجنِ وتركنا من جنى.", "h": ["مشروعية الاعتذار عن الخطأ.", "قد يضطر الحليم إلى أن يقول ما لم يكن يقوله لولا ما وُوجه به من السوء.", "مشروعية الاسترحام والاستعطاف لمن احتاج إلى ذلك، رجاء أن يُرحم ويُعطف عليه.", "حرمة ترك الجاني وأخذ غيره بدلاً منه، إذ هذا من الظلم المحرّم."], "k": "«فأسرّها يوسف في نفسه»… اتُّهم ظلماً فكتم ولم يردّ؛ فهل أملك نفسي عند الاتهام؟"}, {"lbl": "الآيات ٨٠ – ٨٤", "q": "فَلَمَّا ٱسۡتَيۡـَٔسُواْ مِنۡهُ خَلَصُواْ نَجِيّٗاۖ قَالَ كَبِيرُهُمۡ أَلَمۡ تَعۡلَمُوٓاْ أَنَّ أَبَاكُمۡ قَدۡ أَخَذَ عَلَيۡكُم مَّوۡثِقٗا مِّنَ ٱللَّهِ وَمِن قَبۡلُ مَا فَرَّطتُمۡ فِي يُوسُفَۖ فَلَنۡ أَبۡرَحَ ٱلۡأَرۡضَ حَتَّىٰ يَأۡذَنَ لِيٓ أَبِيٓ أَوۡ يَحۡكُمَ ٱللَّهُ لِيۖ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ ﴿٨٠﴾ ٱرۡجِعُوٓاْ إِلَىٰٓ أَبِيكُمۡ فَقُولُواْ يَـٰٓأَبَانَآ إِنَّ ٱبۡنَكَ سَرَقَ وَمَا شَهِدۡنَآ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَيۡبِ حَٰفِظِينَ ﴿٨١﴾ وَسۡـَٔلِ ٱلۡقَرۡيَةَ ٱلَّتِي كُنَّا فِيهَا وَٱلۡعِيرَ ٱلَّتِيٓ أَقۡبَلۡنَا فِيهَاۖ وَإِنَّا لَصَٰدِقُونَ ﴿٨٢﴾ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ﴿٨٣﴾ وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَـٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ ﴿٨٤﴾", "w": [["استيأسوا", "يئسوا."], ["خلصوا نجياً", "اعتزلوا يتناجون في قضيتهم."], ["أخذ عليكم موثقاً", "عهداً وميثاقاً لتأتُنّه به إلا أن يحاط بكم."], ["ومن قبل ما فرطتم", "ومن قبل إضاعتكم لبنيامين فرّطتم في يوسف كذلك."], ["فلن أبرح الأرض", "لن أفارق أرض مصر."], ["وما كنا للغيب حافظين", "لما غاب عنا ولم نعرفه حافظين."], ["العير التي أقبلنا فيها", "أصحاب القافلة التي جئنا معها، وهم قوم كنعانيون."], ["سوّلت لكم أنفسكم", "زيّنت وحسّنت لكم أمراً ففعلتموه."], ["أن يأتيني بهم جميعاً", "بيوسف وأخويه بنيامين وروبيل."], ["وتولى عنهم", "أعرض عن حديثهم."], ["يا أسفى", "يا حزني احضر، هذا أوان حضورك."], ["فهو كظيم", "مغموم مكروب لا يُظهر كربه."]], "m": "لما لم يقبل يوسف استرحامهم يئسوا، فاعتزلوا يتناجون، فقال كبيرهم روبيل: ألم تعلموا أن أباكم قد أخذ عليكم عهداً من الله، ومن قبل فرّطتم في يوسف يوم ألقيتموه في الجب وبعتموه؟ فلن أفارق أرض مصر حتى يأذن لي أبي أو يحكم الله لي بما هو خير، وهو خير الحاكمين. ارجعوا إلى أبيكم فقولوا: يا أبانا إن ابنك سرق، وما شهدنا إلا بما علمنا، حيث رأينا الصواع يُستخرج من رحله، وما كنا للغيب حافظين، ولو علمنا ما يحدث له ما أخذناه، واسأل أهل القرية التي كنا فيها، عاصمة مصر، والقافلة التي أقبلنا فيها من جيرانك الكنعانيين، وإنا لصادقون. فلما قالوه لأبيهم قال: بل زيّنت لكم أنفسكم أمراً، فصبري صبر جميل لا جزع فيه ولا شكاية لأحد غير الله، عسى الله أن يأتيني بهم جميعاً، إنه هو العليم بفقري إليه، الحكيم في تدبيره لأوليائه. وأعرض عن مخاطبتهم وقال: يا أسفى على يوسف، وابيضّت عيناه من الحزن فغلب بياضهما على سوادهما وفقد الإبصار، فهو ممتلئ من الهم مكظوم لا يبثّه لأحد ولا يشكوه لغير ربه.", "h": ["مشروعية المناجاة للتشاور في الأمر الهام.", "مشروعية التذكير بالالتزامات والعهود والمحافظة على ذلك.", "مشروعية النصح، وتزويد المنصوح له بما يقوله ويعمله.", "جواز اتهام البريء لملابسات أو تهمة سابقة.", "جواز إظهار التأسف والحزن والشكوى لله تعالى."], "k": "«عسى الله أن يأتيني بهم جميعاً»… فقد ولدين وما فقد الرجاء؛ فهل يبقى رجائي حيّاً في ضيقي؟"}, {"lbl": "الآيات ٨٥ – ٨٨", "q": "قَالُواْ تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ ﴿٨٥﴾ قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٨٦﴾ يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ ﴿٨٧﴾ فَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَـٰٓأَيُّهَا ٱلۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَٰعَةٖ مُّزۡجَىٰةٖ فَأَوۡفِ لَنَا ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ إِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ ﴿٨٨﴾", "w": [["تالله تفتأ تذكر", "والله لا تزال تذكر يوسف."], ["حرضاً", "مشرفاً على الهلاك لطول مرضك."], ["أشكو بثي", "عظيم حزني، إذ البث الذي لا يُصبر عليه حتى يُبثّ إلى الغير."], ["فتحسسوا", "اطلبوا خبرهما بلطف حتى تصلوا إلى النتيجة."], ["من روح الله", "من رحمة الله."], ["ببضاعة مزجاة", "بدراهم مدفوعة لا يقبلها الناس لرداءتها."], ["يجزي المتصدقين", "يثيب المتصدقين بثواب الدنيا والآخرة."]], "m": "قال بنو يعقوب له إشفاقاً: والله لا تزال تذكر يوسف حتى تكون مشرفاً على الموت أو تكون من الهالكين. قال: إنما أشكو همّي وحزني إلى الله، وأعلم من الله ما لا تعلمون، فرجاؤه في الله كبير، وأن رؤيا يوسف صادقة وسيجمع الله شمله به. يا بنيّ اذهبوا فالتمسوا أخبار يوسف وأخيه بحواسّكم بالسؤال عنهما، ولا تقنطوا من فرج الله ورحمته، إنه لا ييأس من روح الله إلا القوم الكافرون. فامتثلوا وذهبوا إلى مصر، فلما دخلوا على العزيز قالوا: يا أيها العزيز مسّنا وأهلنا الضر من الجدب والمجاعة، وجئنا بدراهم رديئة مدفوعة، فأوف لنا الكيل بها، وتصدّق علينا بقبولها على رداءتها، إن الله يجزي المتصدقين.", "h": ["شدة الحزن تعرّض صاحبها للحَرَض أو الموت.", "تحرم الشكوى لغير الله عز وجل.", "حرمة اليأس من الفرج عند الشدة، ومن الرحمة عند العذاب.", "جواز الشكوى إذا كان المراد بها الكشف عن الحال للإصلاح أو العلاج، كأن يقول المحتاج: إني جائع أو عارٍ، وكأن يقول المريض للطبيب: أشكو ألماً في بطني أو رأسي.", "فضل الصدقة وثواب المتصدقين."], "k": "«إنما أشكو بثي وحزني إلى الله»… لمن أشكو همّي أولاً: للناس أم لربي؟"}, {"lbl": "الآيات ٨٩ – ٩٣", "q": "قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ جَٰهِلُونَ ﴿٨٩﴾ قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ﴿٩٠﴾ قَالُواْ تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا وَإِن كُنَّا لَخَٰطِـِٔينَ ﴿٩١﴾ قَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ ٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّـٰحِمِينَ ﴿٩٢﴾ ٱذۡهَبُواْ بِقَمِيصِي هَٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِي يَأۡتِ بَصِيرٗا وَأۡتُونِي بِأَهۡلِكُمۡ أَجۡمَعِينَ ﴿٩٣﴾", "w": [["لقد آثرك الله علينا", "فضّلك علينا بما منّ عليك من الإنعام والكمال."], ["لا تثريب عليكم", "لا عتب عليكم ولا لوم."]], "m": "لما شكوا إليه ما هم فيه من ضيق الحال رقّ قلبه وفاضت عيناه بالدموع، وأراد أن ينهي إخفاء حاله عليهم، فقال: هل علمتم ما فعلتم بيوسف وأخيه، من إلقائه في الجب وبيعه، والتفريق بينه وبين أبيه وأخيه، إذ أنتم جاهلون بما يصير إليه أمر يوسف؟ قالوا في اندهاش: أإنك لأنت يوسف؟ قال: أنا يوسف وهذا أخي، قد منّ الله علينا فجمع بيننا على أحسن حال، إنه من يتق الله فيقيم فرائضه ويجتنب نواهيه، ويصبر على ذلك وعلى ما يصيبه، فإن الله لا يضيع أجر المحسنين. قالوا: تالله لقد فضّلك الله علينا بالعلم والحلم والفضل، وإن كنا لخاطئين، فكان هذا توبة منهم. قال: لا عتب عليكم اليوم ولا لوم ولا ذكر لما صنعتم، يغفر الله لكم وهو أرحم الراحمين. ثم سألهم عن والده فأخبروه أنه قد عمي من الحزن، فقال: اذهبوا بقميصي هذا فألقوه على وجه أبي يرجع بصيراً، وأتوني بأهلكم أجمعين، وهو تحوّل كامل للأسرة الشريفة من كنعان إلى مصر، تدبيراً من الله العزيز الحكيم.", "h": ["تقرير مبدأ أن المعاصي لن تكون إلا نتيجة للجهل بالله تعالى وجلاله وشرائعه ووعده ووعيده.", "فضل التقوى والصبر، وما لهما من حسن العاقبة.", "فضل الصفح والعفو، وترك عتاب القريب إذا أساء."], "k": "«لا تثريب عليكم اليوم»… عفو بلا عتاب ولا تذكير؛ فمن أحتاج أن أعفو عنه هكذا؟"}]$j$::jsonb then 0 else 1 end;
