insert into public.tdb_cards(topic, i, body) select 159, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٧ – ٧٩", "q": "۞قَالُوٓاْ إِن يَسۡرِقۡ فَقَدۡ سَرَقَ أَخٞ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا يُوسُفُ فِي نَفۡسِهِۦ وَلَمۡ يُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرّٞ مَّكَانٗاۖ وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ ﴿٧٧﴾ قَالُواْ يَـٰٓأَيُّهَا ٱلۡعَزِيزُ إِنَّ لَهُۥٓ أَبٗا شَيۡخٗا كَبِيرٗا فَخُذۡ أَحَدَنَا مَكَانَهُۥٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ ﴿٧٨﴾ قَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذٗا لَّظَٰلِمُونَ ﴿٧٩﴾", "w": [["فأسرّها يوسف في نفسه", "لم يُظهرها لهم."], ["أنتم شر مكاناً", "شرّ منزلة ممن رميتموه بالسرقة."], ["بما تصفون", "بحقيقة ما تصفون، أي تذكرون."], ["أباً شيخاً كبيراً", "أي يعقوب ﵇."], ["معاذ الله", "نعوذ بالله من أن نأخذ من لم نجد متاعنا عنده."], ["متاعنا", "الصواع."]], "m": "بعد أن استخرج يوسف الصواع من متاع أخيه وتقرّر ظاهراً أن بنيامين سرق، قال إخوته: إن يسرق فقد سرق أخ له من قبل، يعنون يوسف أيام صباه، كان يأخذ الطعام فيعطيه للمساكين، وأخذ صنماً لأبي أمه فكسره حتى لا يعبده، وليس هذا من السرقة المذمومة بل هو محمود. فأسرّها يوسف في نفسه ولم يُظهرها لهم، وقال: أنتم شرّ منزلة ممن رميتموه بالسرقة، والله أعلم بحقيقة ما تذكرون. فلما سمعوا ما في قوله من الصرامة قالوا مستعطفين: يا أيها العزيز إن له أباً شيخاً كبيراً يعزّ عليه فراقه، فخذ أحدنا مكانه إنا نراك من المحسنين. قال: معاذ الله أن نأخذ إلا من وجدنا متاعنا عنده، إنا إذاً لظالمون إن أخذنا من لم يجنِ وتركنا من جنى.", "h": ["مشروعية الاعتذار عن الخطأ.", "قد يضطر الحليم إلى أن يقول ما لم يكن يقوله لولا ما وُوجه به من السوء.", "مشروعية الاسترحام والاستعطاف لمن احتاج إلى ذلك، رجاء أن يُرحم ويُعطف عليه.", "حرمة ترك الجاني وأخذ غيره بدلاً منه، إذ هذا من الظلم المحرّم."], "k": "«فأسرّها يوسف في نفسه»… اتُّهم ظلماً فكتم ولم يردّ؛ فهل أملك نفسي عند الاتهام؟"}, {"lbl": "الآيات ٨٠ – ٨٤", "q": "فَلَمَّا ٱسۡتَيۡـَٔسُواْ مِنۡهُ خَلَصُواْ نَجِيّٗاۖ قَالَ كَبِيرُهُمۡ أَلَمۡ تَعۡلَمُوٓاْ أَنَّ أَبَاكُمۡ قَدۡ أَخَذَ عَلَيۡكُم مَّوۡثِقٗا مِّنَ ٱللَّهِ وَمِن قَبۡلُ مَا فَرَّطتُمۡ فِي يُوسُفَۖ فَلَنۡ أَبۡرَحَ ٱلۡأَرۡضَ حَتَّىٰ يَأۡذَنَ لِيٓ أَبِيٓ أَوۡ يَحۡكُمَ ٱللَّهُ لِيۖ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ ﴿٨٠﴾ ٱرۡجِعُوٓاْ إِلَىٰٓ أَبِيكُمۡ فَقُولُواْ يَـٰٓأَبَانَآ إِنَّ ٱبۡنَكَ سَرَقَ وَمَا شَهِدۡنَآ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَيۡبِ حَٰفِظِينَ ﴿٨١﴾ وَسۡـَٔلِ ٱلۡقَرۡيَةَ ٱلَّتِي كُنَّا فِيهَا وَٱلۡعِيرَ ٱلَّتِيٓ أَقۡبَلۡنَا فِيهَاۖ وَإِنَّا لَصَٰدِقُونَ ﴿٨٢﴾ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ﴿٨٣﴾ وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَـٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ ﴿٨٤﴾", "w": [["استيأسوا", "يئسوا."], ["خلصوا نجياً", "اعتزلوا يتناجون في قضيتهم."], ["أخذ عليكم موثقاً", "عهداً وميثاقاً لتأتُنّه به إلا أن يحاط بكم."], ["ومن قبل ما فرطتم", "ومن قبل إضاعتكم لبنيامين فرّطتم في يوسف كذلك."], ["فلن أبرح الأرض", "لن أفارق أرض مصر."], ["وما كنا للغيب حافظين", "لما غاب عنا ولم نعرفه حافظين."], ["العير التي أقبلنا فيها", "أصحاب القافلة التي جئنا معها، وهم قوم كنعانيون."], ["سوّلت لكم أنفسكم", "زيّنت وحسّنت لكم أمراً ففعلتموه."], ["أن يأتيني بهم جميعاً", "بيوسف وأخويه بنيامين وروبيل."], ["وتولى عنهم", "أعرض عن حديثهم."], ["يا أسفى", "يا حزني احضر، هذا أوان حضورك."], ["فهو كظيم", "مغموم مكروب لا يُظهر كربه."]], "m": "لما لم يقبل يوسف استرحامهم يئسوا، فاعتزلوا يتناجون، فقال كبيرهم روبيل: ألم تعلموا أن أباكم قد أخذ عليكم عهداً من الله، ومن قبل فرّطتم في يوسف يوم ألقيتموه في الجب وبعتموه؟ فلن أفارق أرض مصر حتى يأذن لي أبي أو يحكم الله لي بما هو خير، وهو خير الحاكمين. ارجعوا إلى أبيكم فقولوا: يا أبانا إن ابنك سرق، وما شهدنا إلا بما علمنا، حيث رأينا الصواع يُستخرج من رحله، وما كنا للغيب حافظين، ولو علمنا ما يحدث له ما أخذناه، واسأل أهل القرية التي كنا فيها، عاصمة مصر، والقافلة التي أقبلنا فيها من جيرانك الكنعانيين، وإنا لصادقون. فلما قالوه لأبيهم قال: بل زيّنت لكم أنفسكم أمراً، فصبري صبر جميل لا جزع فيه ولا شكاية لأحد غير الله، عسى الله أن يأتيني بهم جميعاً، إنه هو العليم بفقري إليه، الحكيم في تدبيره لأوليائه. وأعرض عن مخاطبتهم وقال: يا أسفى على يوسف، وابيضّت عيناه من الحزن فغلب بياضهما على سوادهما وفقد الإبصار، فهو ممتلئ من الهم مكظوم لا يبثّه لأحد ولا يشكوه لغير ربه.", "h": ["مشروعية المناجاة للتشاور في الأمر الهام.", "مشروعية التذكير بالالتزامات والعهود والمحافظة على ذلك.", "مشروعية النصح، وتزويد المنصوح له بما يقوله ويعمله.", "جواز اتهام البريء لملابسات أو تهمة سابقة.", "جواز إظهار التأسف والحزن والشكوى لله تعالى."], "k": "«عسى الله أن يأتيني بهم جميعاً»… فقد ولدين وما فقد الرجاء؛ فهل يبقى رجائي حيّاً في ضيقي؟"}, {"lbl": "الآيات ٨٥ – ٨٨", "q": "قَالُواْ تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ ﴿٨٥﴾ قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٨٦﴾ يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ ﴿٨٧﴾ فَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَـٰٓأَيُّهَا ٱلۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَٰعَةٖ مُّزۡجَىٰةٖ فَأَوۡفِ لَنَا ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ إِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ ﴿٨٨﴾", "w": [["تالله تفتأ تذكر", "والله لا تزال تذكر يوسف."], ["حرضاً", "مشرفاً على الهلاك لطول مرضك."], ["أشكو بثي", "عظيم حزني، إذ البث الذي لا يُصبر عليه حتى يُبثّ إلى الغير."], ["فتحسسوا", "اطلبوا خبرهما بلطف حتى تصلوا إلى النتيجة."], ["من روح الله", "من رحمة الله."], ["ببضاعة مزجاة", "بدراهم مدفوعة لا يقبلها الناس لرداءتها."], ["يجزي المتصدقين", "يثيب المتصدقين بثواب الدنيا والآخرة."]], "m": "قال بنو يعقوب له إشفاقاً: والله لا تزال تذكر يوسف حتى تكون مشرفاً على الموت أو تكون من الهالكين. قال: إنما أشكو همّي وحزني إلى الله، وأعلم من الله ما لا تعلمون، فرجاؤه في الله كبير، وأن رؤيا يوسف صادقة وسيجمع الله شمله به. يا بنيّ اذهبوا فالتمسوا أخبار يوسف وأخيه بحواسّكم بالسؤال عنهما، ولا تقنطوا من فرج الله ورحمته، إنه لا ييأس من روح الله إلا القوم الكافرون. فامتثلوا وذهبوا إلى مصر، فلما دخلوا على العزيز قالوا: يا أيها العزيز مسّنا وأهلنا الضر من الجدب والمجاعة، وجئنا بدراهم رديئة مدفوعة، فأوف لنا الكيل بها، وتصدّق علينا بقبولها على رداءتها، إن الله يجزي المتصدقين.", "h": ["شدة الحزن تعرّض صاحبها للحَرَض أو الموت.", "تحرم الشكوى لغير الله عز وجل.", "حرمة اليأس من الفرج عند الشدة، ومن الرحمة عند العذاب.", "جواز الشكوى إذا كان المراد بها الكشف عن الحال للإصلاح أو العلاج، كأن يقول المحتاج: إني جائع أو عارٍ، وكأن يقول المريض للطبيب: أشكو ألماً في بطني أو رأسي.", "فضل الصدقة وثواب المتصدقين."], "k": "«إنما أشكو بثي وحزني إلى الله»… لمن أشكو همّي أولاً: للناس أم لربي؟"}, {"lbl": "الآيات ٨٩ – ٩٣", "q": "قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ جَٰهِلُونَ ﴿٨٩﴾ قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ﴿٩٠﴾ قَالُواْ تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا وَإِن كُنَّا لَخَٰطِـِٔينَ ﴿٩١﴾ قَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ ٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّـٰحِمِينَ ﴿٩٢﴾ ٱذۡهَبُواْ بِقَمِيصِي هَٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِي يَأۡتِ بَصِيرٗا وَأۡتُونِي بِأَهۡلِكُمۡ أَجۡمَعِينَ ﴿٩٣﴾", "w": [["لقد آثرك الله علينا", "فضّلك علينا بما منّ عليك من الإنعام والكمال."], ["لا تثريب عليكم", "لا عتب عليكم ولا لوم."]], "m": "لما شكوا إليه ما هم فيه من ضيق الحال رقّ قلبه وفاضت عيناه بالدموع، وأراد أن ينهي إخفاء حاله عليهم، فقال: هل علمتم ما فعلتم بيوسف وأخيه، من إلقائه في الجب وبيعه، والتفريق بينه وبين أبيه وأخيه، إذ أنتم جاهلون بما يصير إليه أمر يوسف؟ قالوا في اندهاش: أإنك لأنت يوسف؟ قال: أنا يوسف وهذا أخي، قد منّ الله علينا فجمع بيننا على أحسن حال، إنه من يتق الله فيقيم فرائضه ويجتنب نواهيه، ويصبر على ذلك وعلى ما يصيبه، فإن الله لا يضيع أجر المحسنين. قالوا: تالله لقد فضّلك الله علينا بالعلم والحلم والفضل، وإن كنا لخاطئين، فكان هذا توبة منهم. قال: لا عتب عليكم اليوم ولا لوم ولا ذكر لما صنعتم، يغفر الله لكم وهو أرحم الراحمين. ثم سألهم عن والده فأخبروه أنه قد عمي من الحزن، فقال: اذهبوا بقميصي هذا فألقوه على وجه أبي يرجع بصيراً، وأتوني بأهلكم أجمعين، وهو تحوّل كامل للأسرة الشريفة من كنعان إلى مصر، تدبيراً من الله العزيز الحكيم.", "h": ["تقرير مبدأ أن المعاصي لن تكون إلا نتيجة للجهل بالله تعالى وجلاله وشرائعه ووعده ووعيده.", "فضل التقوى والصبر، وما لهما من حسن العاقبة.", "فضل الصفح والعفو، وترك عتاب القريب إذا أساء."], "k": "«لا تثريب عليكم اليوم»… عفو بلا عتاب ولا تذكير؛ فمن أحتاج أن أعفو عنه هكذا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (160, 12, 94, 101, 'سورة يوسف ٩٤ – ١٠١', '«إني لأجد ريح يوسف»، و«رب قد آتيتني من الملك… توفني مسلماً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 160) = $j$[{"lbl": "الآيات ٩٤ – ١٠٠", "q": "وَلَمَّا فَصَلَتِ ٱلۡعِيرُ قَالَ أَبُوهُمۡ إِنِّي لَأَجِدُ رِيحَ يُوسُفَۖ لَوۡلَآ أَن تُفَنِّدُونِ ﴿٩٤﴾ قَالُواْ تَٱللَّهِ إِنَّكَ لَفِي ضَلَٰلِكَ ٱلۡقَدِيمِ ﴿٩٥﴾ فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرٗاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٩٦﴾ قَالُواْ يَـٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ ﴿٩٧﴾ قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٩٨﴾ فَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَبَوَيۡهِ وَقَالَ ٱدۡخُلُواْ مِصۡرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ ﴿٩٩﴾ وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ لَهُۥ سُجَّدٗاۖ وَقَالَ يَـٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّي حَقّٗاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ رَبِّي لَطِيفٞ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ﴿١٠٠﴾", "w": [["ولما فصلت العير", "خرجت من عريش مصر متوجّهة إلى أرض فلسطين."], ["إني لأجد ريح يوسف", "أشتمّها، لأن الريح حملتها إليه بأمر الله تعالى."], ["لولا أن تفنّدون", "تسفّهون، لصدّقتموني."], ["إنك لفي ضلالك القديم", "خطئك بإفراطك في حب يوسف."], ["فلما أن جاء البشير", "هو يهوذا الذي حمل إليه القميص الملطّخ بالدم الكذب."], ["فارتد بصيراً", "رجع بصيراً."], ["سوف أستغفر لكم ربي", "أجّل الاستغفار لهم إلى آخر الليل أو إلى ليلة الجمعة."], ["على العرش", "السرير."], ["وخرّوا له سجداً", "سجدوا له تحية وتعظيماً."], ["من البدو", "البادية، بادية الشام."], ["من بعد أن نزغ", "أفسد."], ["لطيف لما يشاء", "لطيف في تدبيره لمن يشاء من عباده، كما لطف بيوسف."]], "m": "هذه أواخر قصة يوسف ﵇: لما خرجت القافلة من عريش مصر تحمل القميص حملت ريح الصّبا ريح يوسف إلى أبيه، فقال: إني لأجد ريح يوسف، لولا أن تسفّهوني لصدّقتموني. قال الحاضرون من أفراد الأسرة: تالله إنك لفي خطئك القديم بإفراطك في حب يوسف. فلما جاء البشير يهوذا ألقى القميص على وجهه فارتدّ بصيراً، فقال لأبنائه: ألم أقل لكم إني أعلم من لطف الله وحسن تدبيره ما لا تعلمون؟ قالوا: يا أبانا استغفر لنا ذنوبنا إنا كنا خاطئين، قال: سوف أستغفر لكم ربي، فأجّل ذلك إلى ساعة الاستجابة، إنه هو الغفور الرحيم. وتحمّلت الأسرة مهاجرة إلى مصر، وكان يوسف والملك ورجال الدولة في استقبالهم، فلما دخلوا عليه ضمّ إليه أبويه وقال: ادخلوا مصر إن شاء الله آمنين، ورفع أبويه على سرير الملك، وخرّوا له سجداً تحية على عادة ذلك الزمان، لا عبادة. وقال: يا أبت هذا تأويل رؤياي من قبل قد جعلها ربي حقاً، وقد أحسن بي إذ أخرجني من السجن، ولم يذكر الجب أدباً، وجاء بكم من البادية، من بعد أن أفسد الشيطان بيني وبين إخوتي، فنسب الإساءة إلى الشيطان تلطيفاً وإذهاباً للهم من نفوس إخوته، إن ربي لطيف لما يشاء، إنه هو العليم بخلقه، الحكيم في تدبيره وصنعه.", "h": ["آية عظيمة هي حمل الريح ريح يوسف على مسافات بعيدة.", "آية أخرى هي ارتداد بصر يعقوب بعد العمى بمجرد أن أُلقي القميص على وجهه.", "كرم يعقوب وحسن عفوه وصفحه عن أولاده، إذ استغفر لهم ربهم فغفر لهم.", "مشروعية الخروج خارج المدينة لاستقبال أهل الكمال والفضل كالحجاج مثلاً.", "صدق رؤيا يوسف ﵇، إذ تمّت حرفياً، فجلس يوسف على عرشه وخرّ له أبواه وإخوته ساجدين.", "قد يتأخر تأويل الرؤيا عشرات السنين، إذ تأخرت رؤيا يوسف أربعين سنة.", "تجلّيات الألطاف الإلهية والرحمات الربانية في هذه القصة في مظاهر عجيبة."], "k": "«من بعد أن نزغ الشيطان بيني وبين إخوتي»… لم يلُمهم في لحظة الفرح؛ فهل أنسب الخصام إلى الشيطان وأطوي صفحته؟"}, {"lbl": "الآية ١٠١", "q": "۞رَبِّ قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّـٰلِحِينَ ﴿١٠١﴾", "w": [["رب", "يا رب، خالقي ورازقي ومالك أمري ومعبودي الذي ليس لي معبود سواه."], ["من الملك", "من بعض الملك، إذ أصبح ملكاً لمصر."], ["تأويل الأحاديث", "تعبير الرؤى."], ["فاطر السماوات والأرض", "خالقهما على غير مثال سابق."], ["أنت وليّي", "متولّي أمري في الحياتين الدنيا والآخرة."]], "m": "هذا آخر الحديث عن قصة يوسف: بعد أن جمع الله شمله بأسرته، وانقلبت المحن: الإلقاء في الجب، والبيع رقيقاً بثمن بخس، وفتنة امرأة العزيز، والسجن سبع سنين، إلى إشراقات: ملك ودولة، وعزّ ورفعة، واجتماع ووئام، وفوق ذلك العلم اللدني والوحي وتأويل الأحاديث، وبعد أن قبض الله والده وتاب على إخوته، تاقت نفس يوسف إلى الملكوت الأعلى وإلى رفقة آبائه إبراهيم وإسحاق ويعقوب، فرفع يديه إلى ربه وقال: رب قد آتيتني من الملك، وعلّمتني من تأويل الأحاديث، فاطر السماوات والأرض، أنت وليّي في الدنيا والآخرة، توفّني مسلماً وألحقني بالصالحين. واستجاب الله دعاءه فلم يلبث إلا قليلاً حتى وافاه الأجل والتحق بآبائه، فسلام عليه وعليهم.", "h": ["مشروعية دعاء الله تعالى والتوسل إليه بأسمائه وصفاته.", "مشروعية العزوف عن الدنيا والرغبة عنها عند حصولها والتمكن منها.", "فضل الشوق إلى الله والحنين إلى رفقة الصالحين في الملكوت الأعلى.", "مشروعية سؤال الموت إن لم يكن لضرّ أو ملل من العبادة أو رغبة في الراحة، لحديث: «لا يتمنّينّ أحدكم الموت لضرّ نزل به»، ولكن شوقاً إلى الله تعالى والالتحاق بالصالحين."], "k": "«توفني مسلماً وألحقني بالصالحين»… في قمّة الملك سأل حسن الخاتمة؛ فهل هي دعائي الدائم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 160;
insert into public.tdb_cards(topic, i, body) select 160, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٤ – ١٠٠", "q": "وَلَمَّا فَصَلَتِ ٱلۡعِيرُ قَالَ أَبُوهُمۡ إِنِّي لَأَجِدُ رِيحَ يُوسُفَۖ لَوۡلَآ أَن تُفَنِّدُونِ ﴿٩٤﴾ قَالُواْ تَٱللَّهِ إِنَّكَ لَفِي ضَلَٰلِكَ ٱلۡقَدِيمِ ﴿٩٥﴾ فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرٗاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٩٦﴾ قَالُواْ يَـٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ ﴿٩٧﴾ قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٩٨﴾ فَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَبَوَيۡهِ وَقَالَ ٱدۡخُلُواْ مِصۡرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ ﴿٩٩﴾ وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ لَهُۥ سُجَّدٗاۖ وَقَالَ يَـٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّي حَقّٗاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ رَبِّي لَطِيفٞ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ﴿١٠٠﴾", "w": [["ولما فصلت العير", "خرجت من عريش مصر متوجّهة إلى أرض فلسطين."], ["إني لأجد ريح يوسف", "أشتمّها، لأن الريح حملتها إليه بأمر الله تعالى."], ["لولا أن تفنّدون", "تسفّهون، لصدّقتموني."], ["إنك لفي ضلالك القديم", "خطئك بإفراطك في حب يوسف."], ["فلما أن جاء البشير", "هو يهوذا الذي حمل إليه القميص الملطّخ بالدم الكذب."], ["فارتد بصيراً", "رجع بصيراً."], ["سوف أستغفر لكم ربي", "أجّل الاستغفار لهم إلى آخر الليل أو إلى ليلة الجمعة."], ["على العرش", "السرير."], ["وخرّوا له سجداً", "سجدوا له تحية وتعظيماً."], ["من البدو", "البادية، بادية الشام."], ["من بعد أن نزغ", "أفسد."], ["لطيف لما يشاء", "لطيف في تدبيره لمن يشاء من عباده، كما لطف بيوسف."]], "m": "هذه أواخر قصة يوسف ﵇: لما خرجت القافلة من عريش مصر تحمل القميص حملت ريح الصّبا ريح يوسف إلى أبيه، فقال: إني لأجد ريح يوسف، لولا أن تسفّهوني لصدّقتموني. قال الحاضرون من أفراد الأسرة: تالله إنك لفي خطئك القديم بإفراطك في حب يوسف. فلما جاء البشير يهوذا ألقى القميص على وجهه فارتدّ بصيراً، فقال لأبنائه: ألم أقل لكم إني أعلم من لطف الله وحسن تدبيره ما لا تعلمون؟ قالوا: يا أبانا استغفر لنا ذنوبنا إنا كنا خاطئين، قال: سوف أستغفر لكم ربي، فأجّل ذلك إلى ساعة الاستجابة، إنه هو الغفور الرحيم. وتحمّلت الأسرة مهاجرة إلى مصر، وكان يوسف والملك ورجال الدولة في استقبالهم، فلما دخلوا عليه ضمّ إليه أبويه وقال: ادخلوا مصر إن شاء الله آمنين، ورفع أبويه على سرير الملك، وخرّوا له سجداً تحية على عادة ذلك الزمان، لا عبادة. وقال: يا أبت هذا تأويل رؤياي من قبل قد جعلها ربي حقاً، وقد أحسن بي إذ أخرجني من السجن، ولم يذكر الجب أدباً، وجاء بكم من البادية، من بعد أن أفسد الشيطان بيني وبين إخوتي، فنسب الإساءة إلى الشيطان تلطيفاً وإذهاباً للهم من نفوس إخوته، إن ربي لطيف لما يشاء، إنه هو العليم بخلقه، الحكيم في تدبيره وصنعه.", "h": ["آية عظيمة هي حمل الريح ريح يوسف على مسافات بعيدة.", "آية أخرى هي ارتداد بصر يعقوب بعد العمى بمجرد أن أُلقي القميص على وجهه.", "كرم يعقوب وحسن عفوه وصفحه عن أولاده، إذ استغفر لهم ربهم فغفر لهم.", "مشروعية الخروج خارج المدينة لاستقبال أهل الكمال والفضل كالحجاج مثلاً.", "صدق رؤيا يوسف ﵇، إذ تمّت حرفياً، فجلس يوسف على عرشه وخرّ له أبواه وإخوته ساجدين.", "قد يتأخر تأويل الرؤيا عشرات السنين، إذ تأخرت رؤيا يوسف أربعين سنة.", "تجلّيات الألطاف الإلهية والرحمات الربانية في هذه القصة في مظاهر عجيبة."], "k": "«من بعد أن نزغ الشيطان بيني وبين إخوتي»… لم يلُمهم في لحظة الفرح؛ فهل أنسب الخصام إلى الشيطان وأطوي صفحته؟"}, {"lbl": "الآية ١٠١", "q": "۞رَبِّ قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّـٰلِحِينَ ﴿١٠١﴾", "w": [["رب", "يا رب، خالقي ورازقي ومالك أمري ومعبودي الذي ليس لي معبود سواه."], ["من الملك", "من بعض الملك، إذ أصبح ملكاً لمصر."], ["تأويل الأحاديث", "تعبير الرؤى."], ["فاطر السماوات والأرض", "خالقهما على غير مثال سابق."], ["أنت وليّي", "متولّي أمري في الحياتين الدنيا والآخرة."]], "m": "هذا آخر الحديث عن قصة يوسف: بعد أن جمع الله شمله بأسرته، وانقلبت المحن: الإلقاء في الجب، والبيع رقيقاً بثمن بخس، وفتنة امرأة العزيز، والسجن سبع سنين، إلى إشراقات: ملك ودولة، وعزّ ورفعة، واجتماع ووئام، وفوق ذلك العلم اللدني والوحي وتأويل الأحاديث، وبعد أن قبض الله والده وتاب على إخوته، تاقت نفس يوسف إلى الملكوت الأعلى وإلى رفقة آبائه إبراهيم وإسحاق ويعقوب، فرفع يديه إلى ربه وقال: رب قد آتيتني من الملك، وعلّمتني من تأويل الأحاديث، فاطر السماوات والأرض، أنت وليّي في الدنيا والآخرة، توفّني مسلماً وألحقني بالصالحين. واستجاب الله دعاءه فلم يلبث إلا قليلاً حتى وافاه الأجل والتحق بآبائه، فسلام عليه وعليهم.", "h": ["مشروعية دعاء الله تعالى والتوسل إليه بأسمائه وصفاته.", "مشروعية العزوف عن الدنيا والرغبة عنها عند حصولها والتمكن منها.", "فضل الشوق إلى الله والحنين إلى رفقة الصالحين في الملكوت الأعلى.", "مشروعية سؤال الموت إن لم يكن لضرّ أو ملل من العبادة أو رغبة في الراحة، لحديث: «لا يتمنّينّ أحدكم الموت لضرّ نزل به»، ولكن شوقاً إلى الله تعالى والالتحاق بالصالحين."], "k": "«توفني مسلماً وألحقني بالصالحين»… في قمّة الملك سأل حسن الخاتمة؛ فهل هي دعائي الدائم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (161, 12, 102, 111, 'سورة يوسف ١٠٢ – ١١١', '«قل هذه سبيلي أدعو إلى الله على بصيرة»، و«لقد كان في قصصهم عبرة لأولي الألباب»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 161) = $j$[{"lbl": "الآيات ١٠٢ – ١٠٦", "q": "ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۖ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ أَجۡمَعُوٓاْ أَمۡرَهُمۡ وَهُمۡ يَمۡكُرُونَ ﴿١٠٢﴾ وَمَآ أَكۡثَرُ ٱلنَّاسِ وَلَوۡ حَرَصۡتَ بِمُؤۡمِنِينَ ﴿١٠٣﴾ وَمَا تَسۡـَٔلُهُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ﴿١٠٤﴾ وَكَأَيِّن مِّنۡ ءَايَةٖ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يَمُرُّونَ عَلَيۡهَا وَهُمۡ عَنۡهَا مُعۡرِضُونَ ﴿١٠٥﴾ وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ ﴿١٠٦﴾", "w": [["ذلك", "إشارة إلى ما قصّ تعالى على رسوله من قصة يوسف وإخوته."], ["من أنباء الغيب", "أخبار الغيب."], ["وما كنت لديهم", "لدى إخوة يوسف."], ["إذ أجمعوا أمرهم", "اتفقوا على إلقاء يوسف في غيابة الجب."], ["وهم يمكرون", "يحتالون على إخراجه وإلقائه في الجب."], ["عليه من أجر", "على القرآن وإبلاغه من ثواب، أي مال."], ["إن هو إلا ذكر", "ما هو إلا موعظة يتعظ بها المؤمنون."]], "m": "بعد ما قصّ تعالى على رسوله ﷺ قصة يوسف وإخوته، وهي من الغيب المحض إذ لم يكن هو ولا قومه يعرفون عن هذه الأحداث شيئاً، وبعضها تمّ في ظلام الليل، وبعضها في ظلام البئر، وبعضها وراء الستور، وبعضها في السجون وقصور الملوك، مع تطاول الزمن، قال: ذلك من أنباء الغيب نوحيه إليك، وما كنت لدى إخوة يوسف إذ أجمعوا أمرهم على التخلّص منه وهم يحتالون. وما أكثر الناس ولو حرصت على إيمانهم بمؤمنين، لأن الإيمان يتعارض مع ما ألفوا من الباطل وشهواتهم، ومن كتب الله شقاءه لا يؤمن بحال، فلا تحزن. وما تسألهم على القرآن وإبلاغه من مال، ولو سألتهم لكان مانعاً من قبول دعوتك، إن هو إلا موعظة للعالمين. وكم من آية في السماوات كالشمس والقمر والكواكب والسحب، وفي الأرض كالجبال والأنهار والأشجار، يمرّون عليها صباح مساء وهم عنها معرضون غير متفكّرين. وما يؤمن أكثرهم بالله رباً خالقاً رازقاً إلا وهم مشركون به أصناماً يعبدونها، وكثير من أهل الجهل في هذه الأمة يدعون غير الله ويذبحون وينذرون لغيره وهم مؤمنون بالله.", "h": ["تقرير النبوة المحمدية بأصدق برهان وأعظم حجة.", "بيان حكم الله في الناس، وهو أن أكثرهم لا يؤمنون، فلا يحزن الداعي ولا يكرب.", "دعوة الله ينبغي أن تُقدَّم إلى الناس مجاناً، وأجر الداعي على الله تعالى الذي يدعو إليه.", "ذم الغفلة وعدم التفكر في الآيات الكونية.", "بيان حقيقة ثابتة، وهي أن غير أهل التوحيد، وإن آمنوا بالله رباً خالقاً رازقاً مدبّراً، أكثرهم يشركون به غيره في بعض صفاته وعباداته."], "k": "«يمرون عليها وهم عنها معرضون»… في طريقي اليوم، كم آية مررت بها دون أن أتفكّر؟"}, {"lbl": "الآيات ١٠٧ – ١٠٩", "q": "أَفَأَمِنُوٓاْ أَن تَأۡتِيَهُمۡ غَٰشِيَةٞ مِّنۡ عَذَابِ ٱللَّهِ أَوۡ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿١٠٧﴾ قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ وَسُبۡحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٠٨﴾ وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰٓۗ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ٱتَّقَوۡاْۚ أَفَلَا تَعۡقِلُونَ ﴿١٠٩﴾", "w": [["غاشية من عذاب الله", "نقمة من نقمه تعالى تغشاهم، أي تحيط بهم."], ["بغتة", "فجأة وهم مقيمون على شركهم وكفرهم."], ["هذه سبيلي", "دعوتي وطريقتي التي أنا عليها."], ["على بصيرة", "على علم يقين مني."], ["وسبحان الله", "تنزيه له وتقديس أن يكون له شريك في ملكه أو معبود سواه."], ["من أهل القرى", "من أهل المدن والأمصار لا من أهل البوادي."], ["للذين اتقوا", "اتقوا الله بأداء فرائضه وترك نواهيه."], ["أفلا تعقلون", "أفلا يعقل هؤلاء المشركون ما يُتلى عليهم فيؤمنوا ويوحّدوا؟"]], "m": "أفأمن هؤلاء المشركون الذين لا يؤمن أكثرهم بالله إلا وهم مشركون، ويمرّون بآيات الله معرضين، أن تأتيهم عقوبة من عذاب الله تغشاهم، أو تأتيهم الساعة فجأة وهم لا يشعرون؟ وهل يوجد من يؤمّنهم غير الله؟ قل أيها الرسول للناس: هذه طريقتي في دعوتي، أدعو إلى الله على علم يقين بمن أدعو إليه وبما أدعو به وبالنتائج المترتبة عليه، أنا ومن اتّبعني من المؤمنين، وسبحان الله تنزيهاً له عن الشريك والولد، وما أنا من المشركين، معلناً البراءة منهم. وما أرسلنا من قبلك إلا رجالاً، لا نساءً ولا ملائكة، نوحي إليهم من أهل المدن والأمصار، إبطالاً لإنكارهم أن يكون الرسول رجلاً. أفلم يسيروا في الأرض للاعتبار فينظروا كيف كان عاقبة من قبلهم كعاد وثمود، أهلكناهم ونجّينا أهل الإيمان مع رسلهم؟ ولدار الآخرة خير للذين اتقوا، دار النعيم المقيم والسلامة من الآفات والهرم والموت، أفلا تعقلون ما يُتلى عليكم وما تشاهدون من الآيات؟", "h": ["التحذير من العقوبات المترتبة على الشرك والمعاصي.", "تقرير عقيدة البعث الآخر.", "تعيّن الدعوة إلى الله تعالى على كل مؤمن تابع للرسول ﷺ.", "تعيّن العلم اليقيني للداعي إلى الله، إذ هو البصيرة المذكورة في الآية.", "وجوب توحيد الله تعالى في ألوهيته وربوبيته وأسمائه وصفاته.", "الرسالة من خصوصيات الرجال، وليس في النساء رسولة.", "بيان ثمرات التوحيد والتقوى في الدنيا والآخرة."], "k": "«أدعو إلى الله على بصيرة أنا ومن اتبعني»… هل أنا ممن اتبعه في الدعوة، وعلى علم؟"}, {"lbl": "الآيتان ١١٠ – ١١١", "q": "حَتَّىٰٓ إِذَا ٱسۡتَيۡـَٔسَ ٱلرُّسُلُ وَظَنُّوٓاْ أَنَّهُمۡ قَدۡ كُذِبُواْ جَآءَهُمۡ نَصۡرُنَا فَنُجِّيَ مَن نَّشَآءُۖ وَلَا يُرَدُّ بَأۡسُنَا عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ ﴿١١٠﴾ لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةٞ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ حَدِيثٗا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿١١١﴾", "w": [["استيأس الرسل", "يئسوا من إيمان قومهم."], ["وظنوا أنهم قد كُذبوا", "ظنّ الأمم المرسل إليهم أن الرسل قد أُخلفوا ما وُعدوا به."], ["ولا يُردّ بأسنا", "عذابنا الشديد."], ["عن القوم المجرمين", "الذين أجرموا على أنفسهم بالشرك والمعاصي، وعلى غيرهم بصرفهم عن الإيمان."], ["لقد كان في قصصهم", "أي الرسل ﵈."], ["ما كان حديثاً يُفترى", "ما كان هذا القرآن حديثاً يُختلق."], ["تصديق الذي بين يديه", "ما قبله من الكتب الإلهية، إذ نزل مصدّقاً لها في الإيمان والتوحيد."]], "m": "وما أرسلنا من قبلك من رسلنا إلا يدعون إلينا ويواصلون دعوتهم، ويتأخّر نصرهم حتى يدبّ اليأس إلى قلوبهم من إيمان قومهم، ويظن أتباعهم أنهم قد أُخلفوا ما وُعدوا به، جاءهم بعد اليأس نصرنا، فنُجّي من نشاء، ولا يُردّ عذابنا عن القوم المجرمين. لقد كان في قصص الرسل مع أممهم، من نجاة المؤمنين وهلاك المكذّبين، عبرة لأصحاب العقول، فيثبت المؤمنون على إيمانهم ويواصلون تقواهم. ما كان هذا القرآن حديثاً في إمكان الإنسان أن يختلق مثله، ولكن تصديق الذي بين يديه من التوراة والإنجيل في أصول الإيمان والتوحيد، وهذا أكبر دليل على أنه وحي مثلهما، وتفصيل كل شيء تحتاج إليه البشرية في دينها، وهدى ينير الطريق، ورحمة لقوم يؤمنون به ويعملون بشرائعه.", "h": ["بيان سنة الله تعالى في تأخّر النصر على رسله وعباده المؤمنين، زيادةً في الإعداد والتمحيص، ثم يأتي نصر الله فيعزّ أولياءه ويذلّ أعداءه.", "التنديد بالإجرام، وهو الإفساد للعقائد والأخلاق والشرائع والأحكام.", "بيان فضل القرآن وما فيه من الهدى والرحمة لمن طلب ذلك منه.", "المؤمنون باعتبار أنهم أحياء هم الذين ينتفعون بهداية القرآن ورحمته."], "k": "«حتى إذا استيأس الرسل جاءهم نصرنا»… النصر يأتي بعد أشد لحظات اليأس؛ فهل أثبت حتى يأتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 161;
insert into public.tdb_cards(topic, i, body) select 161, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠٢ – ١٠٦", "q": "ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۖ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ أَجۡمَعُوٓاْ أَمۡرَهُمۡ وَهُمۡ يَمۡكُرُونَ ﴿١٠٢﴾ وَمَآ أَكۡثَرُ ٱلنَّاسِ وَلَوۡ حَرَصۡتَ بِمُؤۡمِنِينَ ﴿١٠٣﴾ وَمَا تَسۡـَٔلُهُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ﴿١٠٤﴾ وَكَأَيِّن مِّنۡ ءَايَةٖ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يَمُرُّونَ عَلَيۡهَا وَهُمۡ عَنۡهَا مُعۡرِضُونَ ﴿١٠٥﴾ وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ ﴿١٠٦﴾", "w": [["ذلك", "إشارة إلى ما قصّ تعالى على رسوله من قصة يوسف وإخوته."], ["من أنباء الغيب", "أخبار الغيب."], ["وما كنت لديهم", "لدى إخوة يوسف."], ["إذ أجمعوا أمرهم", "اتفقوا على إلقاء يوسف في غيابة الجب."], ["وهم يمكرون", "يحتالون على إخراجه وإلقائه في الجب."], ["عليه من أجر", "على القرآن وإبلاغه من ثواب، أي مال."], ["إن هو إلا ذكر", "ما هو إلا موعظة يتعظ بها المؤمنون."]], "m": "بعد ما قصّ تعالى على رسوله ﷺ قصة يوسف وإخوته، وهي من الغيب المحض إذ لم يكن هو ولا قومه يعرفون عن هذه الأحداث شيئاً، وبعضها تمّ في ظلام الليل، وبعضها في ظلام البئر، وبعضها وراء الستور، وبعضها في السجون وقصور الملوك، مع تطاول الزمن، قال: ذلك من أنباء الغيب نوحيه إليك، وما كنت لدى إخوة يوسف إذ أجمعوا أمرهم على التخلّص منه وهم يحتالون. وما أكثر الناس ولو حرصت على إيمانهم بمؤمنين، لأن الإيمان يتعارض مع ما ألفوا من الباطل وشهواتهم، ومن كتب الله شقاءه لا يؤمن بحال، فلا تحزن. وما تسألهم على القرآن وإبلاغه من مال، ولو سألتهم لكان مانعاً من قبول دعوتك، إن هو إلا موعظة للعالمين. وكم من آية في السماوات كالشمس والقمر والكواكب والسحب، وفي الأرض كالجبال والأنهار والأشجار، يمرّون عليها صباح مساء وهم عنها معرضون غير متفكّرين. وما يؤمن أكثرهم بالله رباً خالقاً رازقاً إلا وهم مشركون به أصناماً يعبدونها، وكثير من أهل الجهل في هذه الأمة يدعون غير الله ويذبحون وينذرون لغيره وهم مؤمنون بالله.", "h": ["تقرير النبوة المحمدية بأصدق برهان وأعظم حجة.", "بيان حكم الله في الناس، وهو أن أكثرهم لا يؤمنون، فلا يحزن الداعي ولا يكرب.", "دعوة الله ينبغي أن تُقدَّم إلى الناس مجاناً، وأجر الداعي على الله تعالى الذي يدعو إليه.", "ذم الغفلة وعدم التفكر في الآيات الكونية.", "بيان حقيقة ثابتة، وهي أن غير أهل التوحيد، وإن آمنوا بالله رباً خالقاً رازقاً مدبّراً، أكثرهم يشركون به غيره في بعض صفاته وعباداته."], "k": "«يمرون عليها وهم عنها معرضون»… في طريقي اليوم، كم آية مررت بها دون أن أتفكّر؟"}, {"lbl": "الآيات ١٠٧ – ١٠٩", "q": "أَفَأَمِنُوٓاْ أَن تَأۡتِيَهُمۡ غَٰشِيَةٞ مِّنۡ عَذَابِ ٱللَّهِ أَوۡ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿١٠٧﴾ قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ وَسُبۡحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٠٨﴾ وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰٓۗ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ٱتَّقَوۡاْۚ أَفَلَا تَعۡقِلُونَ ﴿١٠٩﴾", "w": [["غاشية من عذاب الله", "نقمة من نقمه تعالى تغشاهم، أي تحيط بهم."], ["بغتة", "فجأة وهم مقيمون على شركهم وكفرهم."], ["هذه سبيلي", "دعوتي وطريقتي التي أنا عليها."], ["على بصيرة", "على علم يقين مني."], ["وسبحان الله", "تنزيه له وتقديس أن يكون له شريك في ملكه أو معبود سواه."], ["من أهل القرى", "من أهل المدن والأمصار لا من أهل البوادي."], ["للذين اتقوا", "اتقوا الله بأداء فرائضه وترك نواهيه."], ["أفلا تعقلون", "أفلا يعقل هؤلاء المشركون ما يُتلى عليهم فيؤمنوا ويوحّدوا؟"]], "m": "أفأمن هؤلاء المشركون الذين لا يؤمن أكثرهم بالله إلا وهم مشركون، ويمرّون بآيات الله معرضين، أن تأتيهم عقوبة من عذاب الله تغشاهم، أو تأتيهم الساعة فجأة وهم لا يشعرون؟ وهل يوجد من يؤمّنهم غير الله؟ قل أيها الرسول للناس: هذه طريقتي في دعوتي، أدعو إلى الله على علم يقين بمن أدعو إليه وبما أدعو به وبالنتائج المترتبة عليه، أنا ومن اتّبعني من المؤمنين، وسبحان الله تنزيهاً له عن الشريك والولد، وما أنا من المشركين، معلناً البراءة منهم. وما أرسلنا من قبلك إلا رجالاً، لا نساءً ولا ملائكة، نوحي إليهم من أهل المدن والأمصار، إبطالاً لإنكارهم أن يكون الرسول رجلاً. أفلم يسيروا في الأرض للاعتبار فينظروا كيف كان عاقبة من قبلهم كعاد وثمود، أهلكناهم ونجّينا أهل الإيمان مع رسلهم؟ ولدار الآخرة خير للذين اتقوا، دار النعيم المقيم والسلامة من الآفات والهرم والموت، أفلا تعقلون ما يُتلى عليكم وما تشاهدون من الآيات؟", "h": ["التحذير من العقوبات المترتبة على الشرك والمعاصي.", "تقرير عقيدة البعث الآخر.", "تعيّن الدعوة إلى الله تعالى على كل مؤمن تابع للرسول ﷺ.", "تعيّن العلم اليقيني للداعي إلى الله، إذ هو البصيرة المذكورة في الآية.", "وجوب توحيد الله تعالى في ألوهيته وربوبيته وأسمائه وصفاته.", "الرسالة من خصوصيات الرجال، وليس في النساء رسولة.", "بيان ثمرات التوحيد والتقوى في الدنيا والآخرة."], "k": "«أدعو إلى الله على بصيرة أنا ومن اتبعني»… هل أنا ممن اتبعه في الدعوة، وعلى علم؟"}, {"lbl": "الآيتان ١١٠ – ١١١", "q": "حَتَّىٰٓ إِذَا ٱسۡتَيۡـَٔسَ ٱلرُّسُلُ وَظَنُّوٓاْ أَنَّهُمۡ قَدۡ كُذِبُواْ جَآءَهُمۡ نَصۡرُنَا فَنُجِّيَ مَن نَّشَآءُۖ وَلَا يُرَدُّ بَأۡسُنَا عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ ﴿١١٠﴾ لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةٞ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ حَدِيثٗا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿١١١﴾", "w": [["استيأس الرسل", "يئسوا من إيمان قومهم."], ["وظنوا أنهم قد كُذبوا", "ظنّ الأمم المرسل إليهم أن الرسل قد أُخلفوا ما وُعدوا به."], ["ولا يُردّ بأسنا", "عذابنا الشديد."], ["عن القوم المجرمين", "الذين أجرموا على أنفسهم بالشرك والمعاصي، وعلى غيرهم بصرفهم عن الإيمان."], ["لقد كان في قصصهم", "أي الرسل ﵈."], ["ما كان حديثاً يُفترى", "ما كان هذا القرآن حديثاً يُختلق."], ["تصديق الذي بين يديه", "ما قبله من الكتب الإلهية، إذ نزل مصدّقاً لها في الإيمان والتوحيد."]], "m": "وما أرسلنا من قبلك من رسلنا إلا يدعون إلينا ويواصلون دعوتهم، ويتأخّر نصرهم حتى يدبّ اليأس إلى قلوبهم من إيمان قومهم، ويظن أتباعهم أنهم قد أُخلفوا ما وُعدوا به، جاءهم بعد اليأس نصرنا، فنُجّي من نشاء، ولا يُردّ عذابنا عن القوم المجرمين. لقد كان في قصص الرسل مع أممهم، من نجاة المؤمنين وهلاك المكذّبين، عبرة لأصحاب العقول، فيثبت المؤمنون على إيمانهم ويواصلون تقواهم. ما كان هذا القرآن حديثاً في إمكان الإنسان أن يختلق مثله، ولكن تصديق الذي بين يديه من التوراة والإنجيل في أصول الإيمان والتوحيد، وهذا أكبر دليل على أنه وحي مثلهما، وتفصيل كل شيء تحتاج إليه البشرية في دينها، وهدى ينير الطريق، ورحمة لقوم يؤمنون به ويعملون بشرائعه.", "h": ["بيان سنة الله تعالى في تأخّر النصر على رسله وعباده المؤمنين، زيادةً في الإعداد والتمحيص، ثم يأتي نصر الله فيعزّ أولياءه ويذلّ أعداءه.", "التنديد بالإجرام، وهو الإفساد للعقائد والأخلاق والشرائع والأحكام.", "بيان فضل القرآن وما فيه من الهدى والرحمة لمن طلب ذلك منه.", "المؤمنون باعتبار أنهم أحياء هم الذين ينتفعون بهداية القرآن ورحمته."], "k": "«حتى إذا استيأس الرسل جاءهم نصرنا»… النصر يأتي بعد أشد لحظات اليأس؛ فهل أثبت حتى يأتي؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;